        saved_status = START_TO; /* fixes gcc 4.x warning */
        status = START_TO;
        memset(to_b, 0, sizeof(struct to_body));
        to_b->error = PARSE_OK;
        foo = 0;

        for(tmp = buffer; tmp < end; tmp++) {
                switch(*tmp) {
                        case ' ':
                        case '\t':
                                switch(status) {
                                        case F_CRLF:
                                        case F_LF:
                                        case F_CR:
                                                /*previous=crlf and now =' '*/
                                                status = saved_status;
                                                break;
                                        case URI_ENCLOSED:
                                                to_b->uri.len = tmp - to_b->uri.s;
                                                status = E_URI_ENCLOSED;
                                                break;
                                        case URI_OR_TOKEN:
                                                foo = tmp;
                                                status = MAYBE_URI_END;
                                                break;
                                        case DISPLAY_TOKEN:
                                                foo = tmp;
                                                status = DISPLAY_TOKEN_SP;
                                                break;
                                }
                                break;
                        case '\n':
                                switch(status) {
                                        case URI_OR_TOKEN:
                                                foo = tmp;
                                                status = MAYBE_URI_END;
                                        case MAYBE_URI_END:
                                        case DISPLAY_TOKEN_SP:
                                        case E_DISPLAY_QUOTED:
                                        case END:
                                                saved_status = status;
                                                status = F_LF;
                                                break;
                                        case DISPLAY_TOKEN:
                                                foo = tmp;
                                                saved_status = DISPLAY_TOKEN_SP;
                                                status = F_LF;
                                                break;
                                        case F_CR:
                                                status = F_CRLF;
                                                break;
                                        case F_CRLF:
                                        case F_LF:
